export async function invite(db: Database, email: string) {
  const invitationId = crypto.randomUUID();
  await db.transaction(async (tx) => {
    await tx.insertInvitation({ id: invitationId, email });
    await tx.insertOutbox({ id: invitationId, email, status: "pending", attempts: 0 });
  });
  return { status: 202, body: { invitationId, delivery: "queued" } };
}

