import type { Outbox } from "./ports";

type Query = <T>(sql: string, parameters?: unknown[]) => Promise<{ rows: T[] }>;

export function createOutbox(query: Query): Outbox {
  return {
    async claimNext() {
      const result = await query<{ id: string; email: string }>(`
        UPDATE invitation_outbox SET status = 'leased', attempts = attempts + 1
        WHERE id = (
          SELECT id FROM invitation_outbox WHERE status = 'pending'
          ORDER BY id FOR UPDATE SKIP LOCKED LIMIT 1
        ) RETURNING id, email
      `);
      return result.rows[0] ?? null;
    },
    async markSent(id) {
      await query("UPDATE invitation_outbox SET status = 'sent' WHERE id = $1", [id]);
    },
    async releaseForRetry(id) {
      await query("UPDATE invitation_outbox SET status = 'pending' WHERE id = $1", [id]);
    },
  };
}

