import type { Outbox, MailTransport } from "./ports";

export async function deliverOne(outbox: Outbox, mail: MailTransport) {
  const job = await outbox.claimNext();
  if (job === null) return;
  try {
    await mail.sendInvitation(job.email, { idempotencyKey: job.id });
    await outbox.markSent(job.id);
  } catch {
    await outbox.releaseForRetry(job.id);
  }
}

